export type OperationByName<Name extends OperationName> = Extract<Operation, { operation: Name }>;
export type RequestFor<Name extends OperationName> = OperationByName<Name> extends OperationDescriptor<string, infer Request, unknown> ? Request : never;
export type ResultFor<Name extends OperationName> = OperationByName<Name> extends OperationDescriptor<string, unknown, infer Result> ? Result : never;
export type ResponseFor<Name extends OperationName> = OperationByName<Name> extends { readonly transport: HttpOperationTransport } ? HttpSuccessEnvelope<ResultFor<Name>> : ResultFor<Name>;

export type UnavailableDisposition = "service_not_registered" | "schema_unavailable" | "codec_unavailable" | "route_unavailable" | "capability_disabled" | "host_unsupported";
export interface UnavailableOperationCapability<Name extends string = string> { readonly operation: Name; readonly operationId: string; readonly availability: "unavailable"; readonly disposition: UnavailableDisposition }
export const UNAVAILABLE_OPERATIONS = [
  { operation: "workflow_activate_definition", operationId: "operation.workflow.activate_definition", availability: "unavailable", disposition: "route_unavailable" },
  { operation: "workflow_handoff_issue", operationId: "operation.workflow.handoff_issue", availability: "unavailable", disposition: "route_unavailable" },
  { operation: "workflow_handoff_redeem", operationId: "operation.workflow.handoff_redeem", availability: "unavailable", disposition: "route_unavailable" },
  { operation: "workflow_register_definition", operationId: "operation.workflow.register_definition", availability: "unavailable", disposition: "route_unavailable" },
] as const satisfies readonly UnavailableOperationCapability[];
export type UnavailableOperation = (typeof UNAVAILABLE_OPERATIONS)[number];
export type UnavailableOperationName = UnavailableOperation["operation"];
